using System;

public class ArchitectureDecisionRecord
{
    public int Number { get; set; }
    public string Title { get; set; } = "";
    public string Status { get; set; } = "PROPOSED";
    public string Context { get; set; } = "";
    public string Decision { get; set; } = "";
    public string Consequences { get; set; } = "";

    public string GenerateMarkdown()
    {
        return $"# ADR-{Number:D4}: {Title}\n\n" +
               $"## Status: {Status}\n\n" +
               $"## Context\n{Context}\n\n" +
               $"## Decision\n{Decision}\n\n" +
               $"## Consequences\n{Consequences}";
    }
}

public class Program
{
    public static void Main()
    {
        var adr = new ArchitectureDecisionRecord
        {
            Number = 1,
            Title = "Migrasi Core Banking ke .NET 8 dan PostgreSQL",
            Status = "ACCEPTED",
            Context = "Sistem monolitik lama mengalami masalah skalabilitas pada volume transaksi akhir bulan.",
            Decision = "Mengadopsi .NET 8 dengan Clean Architecture, Dapper, dan PostgreSQL cluster.",
            Consequences = "Performa query meningkat 4x lipat; membutuhkan pelatihan SQL modern bagi tim backend."
        };

        string doc = adr.GenerateMarkdown();
        Console.WriteLine(doc);
    }
}

